// 一致性哈希环（TreeMap 模拟有序环）
TreeMap<Long, String> ring = new TreeMap<>();
int VIRTUAL = 160; // 每个物理节点的虚拟节点数

void addNode(String node) {
    for (int i = 0; i < VIRTUAL; i++) {
        long h = hash(node + "#" + i); // 虚拟节点打散到环上
        ring.put(h, node);
    }
}

String route(String key) {
    long h = hash(key);
    // 顺时针找第一个 >= h 的节点；超过末尾则回到环首
    Map.Entry<Long, String> e = ring.ceilingEntry(h);
    if (e == null) e = ring.firstEntry();
    return e.getValue();
}
